class TestPrimeRLFullSuite(unittest.TestCase):
    def test_full_regression_suite(self):
        with tempfile.TemporaryDirectory(prefix="prime_rl_") as directory:
            root = pathlib.Path(directory)
            with zipfile.ZipFile(BytesIO(base64.b64decode("".join(BUNDLE)))) as archive:
                for item in archive.infolist():
                    target = (root / item.filename).resolve()
                    if not target.is_relative_to(root.resolve()):
                        raise ValueError("Unsafe ZIP path")
                archive.extractall(root)
            project = root / "PRIME_RL_Product_Prototype"
            result = subprocess.run(
                [sys.executable, "-W", "error::ResourceWarning", "-m",
                 "unittest", "discover", "-s", ".", "-p", "test_*.py", "-q"],
                cwd=project, text=True, capture_output=True, timeout=180,
            )
            print(result.stdout[-8000:])
            print(result.stderr[-8000:])
            self.assertEqual(result.returncode, 0, "PRIME-RL regression suite failed")

if __name__ == "__main__":
    unittest.main()
